CREATE TABLE IF NOT EXISTS users(id VARCHAR(80) PRIMARY KEY,username VARCHAR(40) NOT NULL UNIQUE,nickname VARCHAR(80) NOT NULL,password_hash TEXT NOT NULL,role ENUM('student','teacher','admin') NOT NULL DEFAULT 'student',disabled BOOLEAN NOT NULL DEFAULT 0,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3));
CREATE TABLE IF NOT EXISTS auth_sessions(id CHAR(64) PRIMARY KEY,user_id VARCHAR(80) NOT NULL,expires_at DATETIME(3) NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),INDEX(user_id),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS classes(id VARCHAR(80) PRIMARY KEY,name VARCHAR(140) NOT NULL,code VARCHAR(12) NOT NULL UNIQUE,teacher_id VARCHAR(80) NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(teacher_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS class_groups(id VARCHAR(80) PRIMARY KEY,class_id VARCHAR(80) NOT NULL,name VARCHAR(100) NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(class_id) REFERENCES classes(id));
CREATE TABLE IF NOT EXISTS class_members(class_id VARCHAR(80) NOT NULL,user_id VARCHAR(80) NOT NULL,group_id VARCHAR(80) NULL,joined_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY(class_id,user_id),INDEX(user_id),FOREIGN KEY(class_id) REFERENCES classes(id),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS assignments(id VARCHAR(80) PRIMARY KEY,class_id VARCHAR(80) NOT NULL,level_id VARCHAR(80) NOT NULL,title VARCHAR(160) NOT NULL,mode VARCHAR(20) NOT NULL,due_at DATETIME(3) NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),FOREIGN KEY(class_id) REFERENCES classes(id));
CREATE TABLE IF NOT EXISTS chapters(id INT PRIMARY KEY,title VARCHAR(100) NOT NULL,definition JSON NOT NULL);
CREATE TABLE IF NOT EXISTS knowledge_points(id VARCHAR(100) PRIMARY KEY,name VARCHAR(100) NOT NULL);
CREATE TABLE IF NOT EXISTS levels(id VARCHAR(80) PRIMARY KEY,owner_id VARCHAR(80) NULL,number INT NOT NULL,chapter INT NOT NULL,title VARCHAR(100) NOT NULL,status ENUM('draft','published','disabled') NOT NULL,current_version INT NOT NULL,global_published BOOLEAN NOT NULL DEFAULT 0,class_id VARCHAR(80) NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),INDEX(class_id,status),FOREIGN KEY(owner_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS level_versions(level_id VARCHAR(80) NOT NULL,version INT NOT NULL,definition JSON NOT NULL,created_by VARCHAR(80) NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY(level_id,version),FOREIGN KEY(level_id) REFERENCES levels(id));
CREATE TABLE IF NOT EXISTS level_knowledge(level_id VARCHAR(80) NOT NULL,knowledge_id VARCHAR(100) NOT NULL,PRIMARY KEY(level_id,knowledge_id));
CREATE TABLE IF NOT EXISTS game_sessions(id VARCHAR(80) PRIMARY KEY,user_id VARCHAR(80) NOT NULL,mode VARCHAR(20) NOT NULL,level_id VARCHAR(80) NOT NULL,level_version INT NOT NULL,seed BIGINT NOT NULL,state JSON NOT NULL,initial_state JSON NOT NULL,revision INT NOT NULL,status VARCHAR(20) NOT NULL,preview BOOLEAN NOT NULL DEFAULT 0,elapsed_ms BIGINT NOT NULL DEFAULT 0,last_active_at DATETIME(3) NOT NULL,root_id VARCHAR(80) NULL,round INT NOT NULL DEFAULT 1,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),INDEX(user_id,status,updated_at),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS game_events(id VARCHAR(100) NOT NULL,session_id VARCHAR(80) NOT NULL,sequence INT NOT NULL,command JSON NOT NULL,accepted BOOLEAN NOT NULL,message VARCHAR(1500) NOT NULL,state JSON NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY(session_id,id),UNIQUE(session_id,sequence),FOREIGN KEY(session_id) REFERENCES game_sessions(id));
CREATE TABLE IF NOT EXISTS seasons(id VARCHAR(80) PRIMARY KEY,name VARCHAR(100) NOT NULL,active BOOLEAN NOT NULL DEFAULT 1,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3));
CREATE TABLE IF NOT EXISTS teams(id VARCHAR(80) PRIMARY KEY,name VARCHAR(100) NOT NULL,class_id VARCHAR(80) NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3));
CREATE TABLE IF NOT EXISTS team_members(team_id VARCHAR(80) NOT NULL,user_id VARCHAR(80) NOT NULL,PRIMARY KEY(team_id,user_id));
CREATE TABLE IF NOT EXISTS results(id VARCHAR(80) PRIMARY KEY,session_id VARCHAR(80) NOT NULL,user_id VARCHAR(80) NOT NULL,mode VARCHAR(20) NOT NULL,level_id VARCHAR(80) NOT NULL,score INT NOT NULL,stars INT NOT NULL,elapsed_seconds INT NOT NULL,team_id VARCHAR(80) NULL,room_id VARCHAR(80) NULL,season_id VARCHAR(80) NOT NULL,won BOOLEAN NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),UNIQUE(session_id,user_id),INDEX(user_id,mode,season_id),INDEX(mode,season_id,score),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS rooms(id VARCHAR(80) PRIMARY KEY,code VARCHAR(12) NOT NULL UNIQUE,state JSON NOT NULL,status VARCHAR(20) NOT NULL,updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3));
CREATE TABLE IF NOT EXISTS sandbox_projects(id VARCHAR(80) PRIMARY KEY,user_id VARCHAR(80) NOT NULL,name VARCHAR(140) NOT NULL,definition JSON NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),updated_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),INDEX(user_id),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS achievements(user_id VARCHAR(80) NOT NULL,achievement_id VARCHAR(80) NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY(user_id,achievement_id));
CREATE TABLE IF NOT EXISTS audit_logs(id VARCHAR(80) PRIMARY KEY,actor_id VARCHAR(80) NULL,action VARCHAR(100) NOT NULL,target_id VARCHAR(100) NOT NULL,details JSON NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),INDEX(actor_id,created_at),INDEX(action,created_at));
CREATE TABLE IF NOT EXISTS settings(id VARCHAR(80) PRIMARY KEY,value JSON NOT NULL);
CREATE TABLE IF NOT EXISTS assets(id VARCHAR(80) PRIMARY KEY,name VARCHAR(140) NOT NULL,url VARCHAR(500) NOT NULL,license VARCHAR(200) NOT NULL,source VARCHAR(500) NOT NULL,owner_id VARCHAR(80) NOT NULL,created_at DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3));
